package io.flottila.api;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Function;

/**
 * The message as it travels through a flow: an immutable record, every step returns a new one.
 * Headers, props, keys and attachments stay separate fields (ARCHITECTURE §5); {@link #body()}
 * and {@link #views()} are shared by reference across every {@code with*}, and replaced together
 * by {@link #next(Body)}.
 *
 * @param id message id, generated by the runtime's {@link IdGenerator}
 * @param flow flow name
 * @param step number of the step this envelope is the output of (0 = ingress identity)
 * @param headers transport metadata
 * @param props typed flow state, never leaves the runtime
 * @param keys business correlation keys
 * @param body main payload, by reference
 * @param attachments parts by name, by reference
 * @param views memoized parsed views of {@code body}
 * @since 0.1
 */
public record Envelope(String id, String flow, int step, Headers headers, Props props, Keys keys,
                       Body body, Map<String, Part> attachments, Views views) {

    /** Header name of the content type, as transports report it. */
    public static final String H_CONTENT_TYPE = "content-type";

    /** Prop carrying the original message id when this envelope is a replay. */
    public static final Key<String> REPLAY_OF = new Key<>("replayOf");

    /**
     * Prop carrying the attempt of the run this envelope belongs to: set from a message's second run on (the worker's second
     * claim of its item onwards), absent on a first run, dropped by a replay. It scopes the keys of {@link #nextKey(String)}
     * to the run (D-066).
     */
    public static final Key<Integer> ATTEMPT = new Key<>("attempt");

    /** Between a part's name and the attempt that wrote it, in a key of {@link #nextKey(String)}; never in a part's own name. */
    private static final char ATTEMPT_SEPARATOR = '~';

    public Envelope {
        Objects.requireNonNull(id, "id");
        Objects.requireNonNull(flow, "flow");
        Objects.requireNonNull(headers, "headers");
        Objects.requireNonNull(props, "props");
        Objects.requireNonNull(keys, "keys");
        Objects.requireNonNull(body, "body");
        Objects.requireNonNull(views, "views");
        if (step < 0) throw new IllegalArgumentException("step < 0");
        attachments = Map.copyOf(attachments);
    }

    /** Stage 0: what arrived, with empty props, keys and attachments. */
    public static Envelope ingress(String id, String flow, Headers headers, Body body) {
        return new Envelope(id, flow, 0, headers, Props.empty(), Keys.empty(), body, Map.of(), new Views());
    }

    /** The output of the next step: step + 1, the new body, fresh views, everything else carried over. */
    public Envelope next(Body newBody) {
        Objects.requireNonNull(newBody, "body");
        return new Envelope(id, flow, step + 1, headers, props, keys, newBody, attachments, new Views());
    }

    /**
     * The same message one step further: step + 1 with the body and its views shared by reference.
     * This is how a step that only changed headers, props or keys is numbered (ARCHITECTURE §5:
     * step index = position in the flow's steps, ingress is 0).
     */
    public Envelope advance() {
        return new Envelope(id, flow, step + 1, headers, props, keys, body, attachments, views);
    }

    /** The key of the next step's main payload: {@code nextKey(BlobKey.BODY)}. */
    public BlobKey nextKey() {
        return nextKey(BlobKey.BODY);
    }

    /**
     * The key a step writes {@code part} of the body it hands on under: (id, step + 1, part) on a first run, the part suffixed
     * {@code ~<attempt>} on a run whose {@link #ATTEMPT} is 2 or more — so each key is written by one run only and a rerun
     * never writes over the bytes an earlier run left (D-066). An attempt that is absent, 1, 0 or negative adds no suffix.
     *
     * @throws NullPointerException if {@code part} is null
     * @throws IllegalArgumentException if {@code part} contains {@code ~}, the attempt separator, whatever the attempt
     */
    public BlobKey nextKey(String part) {
        if (part.indexOf(ATTEMPT_SEPARATOR) >= 0) {
            throw new IllegalArgumentException("part '" + part + "' contains '" + ATTEMPT_SEPARATOR + "', which separates a part from its attempt");
        }
        int attempt = props.get(ATTEMPT).orElse(1);
        return new BlobKey(id, step + 1, attempt >= 2 ? part + ATTEMPT_SEPARATOR + attempt : part);
    }

    public Envelope withHeader(String name, String value) {
        return new Envelope(id, flow, step, headers.with(name, value), props, keys, body, attachments, views);
    }

    public Envelope withHeaders(Map<String, String> extra) {
        return new Envelope(id, flow, step, headers.withAll(extra), props, keys, body, attachments, views);
    }

    public <T> Envelope with(Key<T> key, T value) {
        return new Envelope(id, flow, step, headers, props.with(key, value), keys, body, attachments, views);
    }

    public Envelope withKey(String name, String value) {
        return new Envelope(id, flow, step, headers, props, keys.with(name, value), body, attachments, views);
    }

    public Envelope withAttachment(Part part) {
        var m = new HashMap<>(attachments);
        m.put(part.name(), part);
        return new Envelope(id, flow, step, headers, props, keys, body, m, views);
    }

    public Envelope withId(String newId) {
        return new Envelope(newId, flow, step, headers, props, keys, body, attachments, views);
    }

    /** A parsed view of the body, computed once per body and shared with every envelope carrying it. */
    public <T> T view(Class<T> type, Function<Body, T> parser) {
        return views.get(type, () -> parser.apply(body));
    }

    public Optional<String> header(String name) {
        return Optional.ofNullable(headers.get(name));
    }

    public <T> Optional<T> get(Key<T> key) {
        return props.get(key);
    }

    public Optional<String> key(String name) {
        return Optional.ofNullable(keys.get(name));
    }
}
